cd /home/runner/work/PlayGround/PlayGround && node --input-type=module -e "
import { createGame, marketRows, buyGoods, sellGoods, startTravel, resolveEvent, checkStatus, continueTrading, buyTransport, netWorth, routeQuote } from './src/engine.js';
import { CITIES, CITY_BY_ID, GOODS } from './src/data.js';
let s = createGame('Sim', 7);
let guard = 0;
while (guard++ < 300 && s.status === 'playing') {
  if (s.event) { resolveEvent(s, 0); continue; }
  // sell anything profitable vs local export baseline
  for (const row of marketRows(s)) if (row.owned > 0 && row.imported) sellGoods(s, row.id, row.owned);
  // buy all exports if affordable
  for (const row of marketRows(s)) if (row.exported) buyGoods(s, row.id, Math.min(25, 9999));
  // upgrade towards donkey/wagon
  if (s.gold > 2500 && !s.owned.includes('wagon')) buyTransport(s, 'wagon');
  else if (s.gold > 500 && !s.owned.includes('donkey')) buyTransport(s, 'donkey');
  // pick a random other city
  const dests = CITIES.filter(c => c.id !== s.cityId);
  const dest = dests[(guard * 7) % dests.length];
  const q = routeQuote(s, dest.id);
  if (s.energy < q.energy + 10) { s.energy = 100; s.water = 20; s.rations = 20; s.life = 100; }
  startTravel(s, dest.id);
  if (s.life < 30) { s.life = 100; }
  checkStatus(s);
  if (guard % 30 === 0) console.log('step', guard, 'day', s.day, 'city', s.cityId, 'gold', s.gold, 'net', netWorth(s));
}
console.log('END', s.status, 'day', s.day, 'city', s.cityId, 'gold', s.gold, 'net', netWorth(s), 'logs', s.log.length);
console.log(s.log.slice(-5).map(l=>l.kind+': '+l.text).join('\n'));
console.log('finite', [s.gold,s.life,s.energy,s.thirst,s.hunger,s.water,s.rations].every(Number.isFinite));
"

